76	  } else if (!cli.objdump.empty()) {
77	    err = "--objdump requires --kanata";
78	    return {};
79	  }
80	
81	  // Warmup window last (any trigger; 0/absent contributes nothing).
82	  if (!cli.vsim_warmup_icount.empty() && cli.vsim_warmup_icount != "0") {
83	    out.push_back("--vsim-warmup-icount");
84	    out.push_back(cli.vsim_warmup_icount);
85	  }
86	  return out;
87	}
